                    b.ToTable("NPCDialogues");

                    b.HasData(
                        new
                        {
                            NPCDialogueId = 1,
                            Content = "Ah... a new face, and not one born of these woods. Welcome to the Elf Forest, traveler.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 127,
                            Content = "You did not wander in here. The forest awakened you at its edge, and the forest does not wake strangers.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 2,
                            Content = "For a thousand years this forest kept itself in peace. Now something gathers in the dark beneath the roots.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 94,
                            Content = "The Origin Tree at our heart is sickening. Its leaves fall in high summer, and the animals no longer sleep here.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 128,
                            Content = "A hundred of my people have walked past those roots and heard nothing. You heard it call before you opened your eyes. No one else could.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 3,
                            Content = "So the Origin Tree chose you, and I must trust its choosing. I am Elder Rowan. Speak with me when you are ready to begin.",
                            DisplayOrder = 6,
                            IsActive = true,
                            LinkedQuestId = 1,
                            NPCId = 1,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 4,
                            Content = "Before anything else, I must beg medicine of you. Eleven of my village lie in the healing hall, and my stores are almost gone.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 129,
                            Content = "The rot came up through the well water. The children fell first, then whoever carried them. Salve buys them days, no more than that.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 5,
                            Content = "By the old willow clearing grows a white flower that only opens where the air is still clean. Crushed with spring water, it is the one salve that answers this sickness.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 95,
                            Content = "Where those flowers still bloom, the curse has not yet reached. They are medicine and warning both.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 130,
                            Content = "My knees will not carry me that far anymore. Bring me the flowers and my people live through the week. That is the whole of it.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 6,
                            Content = "Go to the clearing and gather 3 White Flowers for me. Take care, even slimes wander there now.",
                            DisplayOrder = 6,
                            IsActive = true,
                            LinkedQuestId = 2,
                            NPCId = 1,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 7,
                            Content = "Back already? Let me see your hands... ah, you found them.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 3,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 8,
                            Content = "Not a petal bruised. Three flowers, three doses. The healing hall will have them before nightfall, and the children will sleep.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 3,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 131,
                            Content = "I sent a stranger into cursed woods for people you had never met, and you went without asking payment. You have proven yourself.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 3,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 96,
                            Content = "We do not teach our craft outside the bloodline. For you I will break that rule. Let me teach you the First Elven Technique.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 3,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 9,
                            Content = "Hold still. Breathe with the roots, as we do... there. It is yours now, with an old elf's thanks.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 3,
                            NPCId = 1,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 10,
                            Content = "The technique is in you now, but a technique you have not called upon is no better than one you never learned.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 4,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 11,
                            Content = "Every warrior in this world channels power through learned technique. Bare fists will not answer what waits out there.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 4,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 97,
                            Content = "Set it where your hand can reach it without thinking. In a fight you will not have time to remember.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 4,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 12,
                            Content = "Open your Skill Panel and equip the First Elven Technique. Do not step past the treeline without it.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 4,
                            NPCId = 1,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 13,
                            Content = "Good. I can feel the power settled in you now. It must be tested before it is trusted.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 5,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 14,
                            Content = "The outskirts crawl with little slimes. They were harmless once, now they hunt in packs.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 5,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 98,
                            Content = "They are the curse's smallest children. Where they spread, the soil dies behind them.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 5,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 15,
                            Content = "Go out and defeat 3 little slimes, then return and tell me what you felt out there.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 5,
                            NPCId = 1,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 16,
                            Content = "You handled them cleanly. But the slimes are only spillage from something far worse.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 6,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 17,
                            Content = "Deep in the swamp lies a Demon. The water rots around it, and the corruption creeps closer each night.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 6,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 99,
                            Content = "Our scouts say the beast broods over some old relic down there. A seal of some kind, they think. I am no scholar, and none of them got close enough to be sure.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 6,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 132,
                            Content = "What it is, and whether it matters, I cannot tell you. Lyra at the Origin Tree is older than every elf alive. Bring it to her and she will know.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 6,
                            NPCId = 1,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 18,
                            Content = "Destroy the Swamp Demon and take whatever it is guarding. Stopping the rot at its source is what matters.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 6,
                            NPCId = 1,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 19,
                            Content = "Come closer, brave one. I am Lyra, not elf and not ghost. I am the spirit of the Origin Tree itself.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 20,
                            Content = "Look at my bark. The curse has reached my heartwood, and I am dying slowly, from the inside outward.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 133,
                            Content = "Now show me what you took from the swamp... ah. Rowan sent you here not knowing, did he. Hold it up, child.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 134,
                            Content = "This is a Seal Book. The first of them to see daylight in an age, and no living elf has ever held one.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 100,
                            Content = "Long ago the elders bound an ancient power into four such books. That binding has broken, and the leak is what poisons me.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 135,
                            Content = "Four books, scattered and guarded. They are not treasure, they are the lock on my heartwood. Nothing else will save me.",
                            DisplayOrder = 6,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 21,
                            Content = "Only the 4 Seal Books can cleanse me. You hold the first already, find the remaining three, and hurry!",
                            DisplayOrder = 7,
                            IsActive = true,
                            LinkedQuestId = 7,
                            NPCId = 2,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 22,
                            Content = "Heh... so you are the little errand-runner gathering up the Seal Books.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 8,
                            NPCId = 3,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 23,
                            Content = "You carry them and do not even know what they are, or whose hand cursed that tree.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 8,
                            NPCId = 3,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 101,
                            Content = "The elves told you a story with the ugly parts cut out. I can show you what they buried.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 8,
                            NPCId = 3,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 24,
                            Content = "The truth waits through this portal. Follow me, or stay and keep watering a dying tree.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 8,
                            NPCId = 3,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 25,
                            Content = "Steady, traveler. That portal spat us both out here on the beach, and the cloaked one is long gone.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 9,
                            NPCId = 4,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 26,
                            Content = "We are far from the forest now, with no coin between us and no way back that I can see.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 9,
                            NPCId = 4,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 102,
                            Content = "This is farming country. Folk here trade a day of work for supper, and honest work is easy to find.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 9,
                            NPCId = 4,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 27,
                            Content = "Go and speak with Fa, the farmer just up the path. He always needs hands.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 9,
                            NPCId = 4,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 28,
                            Content = "Drake sent you? Good timing, stranger. My back is not what it was.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 10,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 29,
                            Content = "The whole field came ripe at once, and the harvest cart leaves for the city at dusk.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 10,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 103,
                            Content = "Mind the ones that glow faintly. An enchanted pumpkin keeps a lantern lit all winter, that is why the city pays.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 10,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 30,
                            Content = "Collect 8 Enchanted Pumpkins for me and I will see you fed tonight.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 10,
                            NPCId = 7,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 31,
                            Content = "Eight, and not one bruised. You work like a farmhand born, not a wanderer.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 11,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 32,
                            Content = "Now the hard half of the job. These are owed at the city gate before nightfall.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 11,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 104,
                            Content = "I would carry them myself, but no one from this farm has come back from that road in a week.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 11,
                            NPCId = 7,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 33,
                            Content = "Take them to the guard Tristan at the ruined city, and tell him Fa sent you.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 11,
                            NPCId = 7,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 34,
                            Content = "Halt! Who goes... ah, pumpkins from Fa. Set them down, you may be the last delivery this gate sees.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 12,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 35,
                            Content = "Something is wrong inside. No bells, no market noise, no smoke from a single chimney since dawn.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 12,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 105,
                            Content = "I am Tristan, and my orders bind me to this gate. I cannot take one step past it, even now.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 12,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 36,
                            Content = "Go in and look at the fallen with your own eyes. Then come back and tell me the truth of it.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 12,
                            NPCId = 5,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 37,
                            Content = "All of them? Every soul in the city, cut down where they stood? Gods, I stood here and heard nothing.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 13,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 38,
                            Content = "No bandit crew does this in one night. Whatever walked in there was not a man with a sword.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 13,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 106,
                            Content = "There is one person left who might stand against it. Arthur, the silver knight, camped in the old ruins.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 13,
                            NPCId = 5,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 39,
                            Content = "Find Arthur and report what you saw. Go, before whatever did this moves on to the next town.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 13,
                            NPCId = 5,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 40,
                            Content = "Lower your guard, I am no enemy. I am Arthur, once called the silver knight of this city.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 14,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 41,
                            Content = "I met the thing that emptied these streets. It broke something inside me and sealed my power away.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 14,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 107,
                            Content = "I cannot lift my blade again. But a blade is only steel, what matters is the hand that learns to swing it.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 14,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 42,
                            Content = "Clear my old training dungeon. Survive it, and I will give you everything I have left. Go!",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 14,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 136,
                            Content = "The streets are quieter. But quiet is not the same as ready, and a dragon is not a ghoul in an alley.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 15,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 137,
                            Content = "I fought one once believing I was ready. You have seen what is left of me. So you will earn it in four trials.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 15,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 138,
                            Content = "The robbers took the eastern camp the night the city fell. They prey on whoever still crawls out of here alive.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 15,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 139,
                            Content = "Clear 6 of them from the Robber Camp. That is the first trial. Go.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 15,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 140,
                            Content = "One trial down, and you came back on your own feet again. Good.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 16,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 141,
                            Content = "The second is the haunted quarter - ghosts, necromancers, and the red guard. My own men, still standing their posts, still dead.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 16,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 142,
                            Content = "I could never walk that street again. A dragon will not care how brave you felt in daylight.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 16,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 143,
                            Content = "Put down 10 in the Haunted Quarter. Second trial. Move.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 16,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 144,
                            Content = "Two trials, two returns. I am beginning to believe the city might keep you.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 17,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 145,
                            Content = "The third is the ground south of the ruins. Goblins hold it, spear and axe together, and they fight as a pack.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 17,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 146,
                            Content = "A dragon will not come at you alone either. Learn to hold when more than one thing wants you dead.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 17,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 147,
                            Content = "Break 3 of them in the Goblin Grounds. Third trial.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 17,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 148,
                            Content = "Three trials done. You have fought packs, and ghosts, and men. One thing is left that you have not fought.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 18,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 149,
                            Content = "The warband you broke answers to a warlord, and he is still down there holding what is left of them.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 18,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 150,
                            Content = "One enemy, bigger than you, who does not retreat and does not tire. That is the shape of a dragon fight. Learn it here where I can still pull you out.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 18,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 151,
                            Content = "Kill the Goblin Warlord. Finish the last trial and I will tell you everything.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 18,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 46,
                            Content = "You came back quieter than you left. That is how I know the fighting took hold in you.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 19,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 47,
                            Content = "Then hear the rest of it. The monsters were never the cause. Something older nests above the ruins.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 19,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 109,
                            Content = "A dragon. It is the thing that broke this city, and the thing that broke me. I have carried that shame for years.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 19,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 48,
                            Content = "Finish what I could not. Climb to its nest and slay the dragon!",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 19,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 49,
                            Content = "The dragon is dead. I felt it go — the whole city breathed out at once. Thank you.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 20,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 50,
                            Content = "You want to know about the cloaked one. Yes. He passed through here before the dragon ever came.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 20,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 110,
                            Content = "He carries something that should have stayed sealed. Wherever he walks, the land sickens behind him.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 20,
                            NPCId = 6,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 51,
                            Content = "He went north, into the frozen lands. Follow him to the Frozen Mountains. I will hold this city.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 20,
                            NPCId = 6,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 173,
                            Content = "Far enough. I am Cedric — captain, if you are being generous. These fields are mine to hold until the Queen can spare someone better.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 21,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 174,
                            Content = "You came up the ice road, so you saw the state of it. Something crawled out of the snow after the war and it has been eating this valley one field at a time.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 21,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 175,
                            Content = "The ice slimes come further in every night and freeze whatever they touch. Half my company are farmers holding spears they do not know how to use. I have buried four of them this month.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 21,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 54,
                            Content = "You want me to take you seriously, stranger? They are out on the fields right now. Kill 8 of them. Then we can talk about who you are.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 21,
                            NPCId = 14,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 55,
                            Content = "The fields are quiet. My people walked out to the grain stores without an escort for the first time in a month. Come here — I owe you a word.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 21,
                            NPCId = 14,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 176,
                            Content = "I had you down as one more sellsword chasing coin up the ice road. It seems you are not. I have watched men with ten years of service do less than you did out there.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 22,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 177,
                            Content = "So I will tell you what I would not have told you this morning. The Queen has been searching — quietly — for someone with the strength to stand against what is coming for this kingdom.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 22,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 178,
                            Content = "She has asked every captain on this mountain, and every captain has sent back the same answer: no one. I am tired of writing that answer.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 22,
                            NPCId = 14,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 179,
                            Content = "Go up to the citadel and stand in front of Roselyn Aurora. I am sending a runner ahead of you — for once with a name in it.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 22,
                            NPCId = 14,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 180,
                            Content = "Cedric's runner reached me an hour before you did. That man does not praise people, so I read it twice. Stay a moment — there are things you should hear from me and not from a soldier.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 22,
                            NPCId = 8,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 52,
                            Content = "So you are the one Cedric put a name to. I am Roselyn Aurora, and what is left of this kingdom is mine to hold.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 53,
                            Content = "It was not always like this. Once these were the quiet lands — snow fell all winter and killed nothing, and no one here carried a sword.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 111,
                            Content = "Then the codex came. It took the four Seal Books and drank the strength of the Origin Tree, and everything it passed turned wrong. What you are standing in is only what that war left behind.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 152,
                            Content = "Cedric's company is the whole of my army. Farmers holding spears, and a captain who has stopped asking me for reinforcements because he knows there are none.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 56,
                            Content = "You passed the statue at my gate. King Aurelian — the ancient king this whole kingdom still honours, and the reason any of it is still standing.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 112,
                            Content = "He spent his life holding back the codex's leavings so that this little peace would outlive him. It did. Barely.",
                            DisplayOrder = 6,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 153,
                            Content = "I cannot answer what you really came to ask. But there is a priest near here — Zephyr. He studies the old magics, and he has studied them longer than I have been queen.",
                            DisplayOrder = 7,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 57,
                            Content = "Carry the Magic Flour I gave you to him — and ask him everything you have been asking me.",
                            DisplayOrder = 8,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 8,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 58,
                            Content = "The Queen's flour, and a courier still breathing. Welcome, hero from far away. I have been on this mountain thirty years chasing one question: how four holy books vanished out of a sealed world.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 23,
                            NPCId = 9,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 59,
                            Content = "Thirty years, and the answer keeps moving. But there is a nearer trouble, and it will not wait for my research.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 24,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 89,
                            Content = "The ice dragons have stopped behaving like animals. Something is steering them — and they have begun coming down on the people below.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 24,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 113,
                            Content = "Five of them circle the peak. Young, all of them. Whatever holds their reins made them hungry in a way no beast should be.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 24,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 60,
                            Content = "Climb the peak and put down all 5. May I ask that of a stranger?",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 24,
                            NPCId = 9,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 154,
                            Content = "The peak is silent. Sit down, hero — I will tell you the part I have never told the Queen.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 24,
                            NPCId = 9,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 155,
                            Content = "The codex may not have been evil to begin with. I think it was something else once, and a power turned it.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 156,
                            Content = "Dark magic. Strength that gives freely and takes greed as its price. Am I certain? No. I am not certain of any of it.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 157,
                            Content = "But look at the beasts here. I studied them before the great war — gentle things, no harm in them. After it, not one of them was itself. Something settled into them, like a taint in the blood.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 158,
                            Content = "You want somewhere else to look? There is one place. Dangerous, and cut off from the capital long ago — the forbidden land north of here, The Doomed Land of Snow. Find the guard Roland at the boundary stones. He is a friend of mine.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 9,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 61,
                            Content = "Halt! This ground is under ban and no one goes in. Who are you?",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 62,
                            Content = "A knight sent to recover the stolen books... I see. Then you did not climb all this way for the view. You mean to go inside the ban.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 114,
                            Content = "Then I will not stand in your way. But hear this: two ancient things still live in there, and both of them are dangerous.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 159,
                            Content = "What are they? I do not truly know. The legend says one is a giant made of stone. The other is a mystery — since the old hero sealed this place, no one has dared walk in far enough to find out.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 63,
                            Content = "Go, then. The way is open, and I will keep the road behind you.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 25,
                            NPCId = 10,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 64,
                            Content = "So it was here all along. Now I know why my order was told to guard this place and never once to enter it.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 26,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 65,
                            Content = "And the seal still holds. One of the four old Seal Books lies at the heart of the ban — the Golem Seal Book.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 26,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 115,
                            Content = "Two guardians stand over it: the stone giant, and the spirit that never leaves his side. The elders left them there to keep every hand off that book, mine included.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 26,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 66,
                            Content = "Put down both of them and take the Golem Seal Book. It is worth more in your hands than under my ban.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 26,
                            NPCId = 10,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 160,
                            Content = "You have the book. But you did not come out of there looking like a man who won a fight — come here and tell me what you saw.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 26,
                            NPCId = 10,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 161,
                            Content = "So that is what was sleeping under my ban. Say it again, slowly — I want to be sure I have it right before I write it down.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 162,
                            Content = "The golem was gentle once. Not a weapon, not a guardian — he lived close to people and helped anyone who asked him.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 163,
                            Content = "And the fairy — he pulled her out of the hands of spirit-traders, men who sold her kind by weight. She never forgot it. She stayed at his side from that day to repay him.",
                            DisplayOrder = 3,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 164,
                            Content = "Then the darkness came down on these lands, and he stood against it — for the villages, not for himself. It was stronger. It did not kill him; it put him into a sleep that went on for years.",
                            DisplayOrder = 4,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 165,
                            Content = "The fairy was terrified. She went to the hero of that age and begged him for help — that is the hero whose statue the Queen still keeps at her gate.",
                            DisplayOrder = 5,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 166,
                            Content = "Two months after the codex fled this place, the golem finally woke — and it was her doing. She had just learned a blessing, and she spent it on him.",
                            DisplayOrder = 6,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 167,
                            Content = "But what woke was not what fell asleep. He behaved wrongly. He struck at the people he used to carry water for.",
                            DisplayOrder = 7,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 168,
                            Content = "And yet he was clear-headed sometimes. Clear enough to understand what was creeping through him — and to decide what to do about it.",
                            DisplayOrder = 8,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 169,
                            Content = "He walked into the forbidden land himself. Shut himself in. Wiped out every road and marker so no one could follow him in. That is the ban I have been standing guard over for eleven years — a cage a man built for himself.",
                            DisplayOrder = 9,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 170,
                            Content = "And she went in with him. Knowing what he had become. She never left his side, right up until you.",
                            DisplayOrder = 10,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 171,
                            Content = "Then it is confirmed, and I will carry it to the Queen: no demon, no evil born evil. Someone was corrupted by a dark power — and everything since has followed from that.",
                            DisplayOrder = 11,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 172,
                            Content = "You said you would come back for those two and set them right. Hold to that, hero. I will keep the ban open for the day you do.",
                            DisplayOrder = 12,
                            IsActive = true,
                            LinkedQuestId = 27,
                            NPCId = 10,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 67,
                            Content = "Those bones were my neighbours once. I left Tide-Knell for the king's army, and returned to find every soul walking without flesh.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 28,
                            NPCId = 11,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 68,
                            Content = "I have guarded this valley for years, cutting down friends who rise again by moonrise. Help me put 12 of them down.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 28,
                            NPCId = 11,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 69,
                            Content = "Recover five keepsakes from Tide-Knell. Let me remember the people I am forced to fight.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 29,
                            NPCId = 11,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 70,
                            Content = "Find the memories and my last letter. Natalie deserves to know I came home too late, not that I abandoned her.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 32,
                            NPCId = 11,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 71,
                            Content = "My mother died, my father went to war, and Tide-Knell called an orphan bad luck. Then a voice beneath the well called me by name.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 30,
                            NPCId = 12,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 72,
                            Content = "It promised friends who would never abandon me. I believed it. Please dig beside the well and lift out my skull.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 30,
                            NPCId = 12,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 73,
                            Content = "The voice still whispers. Find three traces around the well and make it answer for the promise it made.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 31,
                            NPCId = 12,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 74,
                            Content = "I was lonely, but the choice was mine. If you can still pity me, bury me beneath the ivy tree.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 33,
                            NPCId = 12,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 75,
                            Content = "If the earth accepts me, Tide-Knell may sleep. Take my Mystic Key and go to the island.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 33,
                            NPCId = 12,
                            ResponseType = "Reward"
                        },
                        new
                        {
                            NPCDialogueId = 76,
                            Content = "Natalie's key opens the bridge. Use it at the gate, then let the Elf Guard finish what I could not.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 34,
                            NPCId = 11,
                            ResponseType = "Quest"
                        },
                        new
                        {
                            NPCDialogueId = 77,
                            Content = "The prisoner was King Aderyn, my closest friend. He accepted two Seal Books so the forests would not bear the whole curse.",
                            DisplayOrder = 1,
                            IsActive = true,
                            LinkedQuestId = 35,
                            NPCId = 13,
                            ResponseType = "None"
                        },
                        new
                        {
                            NPCDialogueId = 78,
                            Content = "Gather five Ancient Leaves. They may open the crypt without destroying what remains of him.",
                            DisplayOrder = 2,
                            IsActive = true,
                            LinkedQuestId = 35,
